import json
import requests
import chardet
API_URL = "http://api.example.com/data"
def task_func(url=API_URL, from_encoding=None, to_encoding="utf8"):
    response = requests.get(url, timeout=5)
    content = response.content
    if not content:
        return {}
    src_enc = from_encoding if from_encoding else chardet.detect(content).get('encoding')
    if not src_enc:
        raise ValueError("Unable to detect encoding for non-empty content")
    text = content.decode(src_enc)
    normalized_bytes = text.encode(to_encoding)
    normalized_text = normalized_bytes.decode(to_encoding)
    return json.loads(normalized_text)

