                    df = pd.DataFrame([data])
            except Exception:
                df = pd.DataFrame([data])
        else:
            df = pd.DataFrame([{"value": data}])
        return df
    finally:
        if os.path.exists(TARGET_JSON_FILE):
            os.remove(TARGET_JSON_FILE)

