import re
import urllib.parse
import requests
import json
def task_func(myString, API_KEY):
    trailing = '.,;:)"\'>]'
    url_matches = re.findall(r'(https?://[^\s]+)', myString)
    www_matches = re.findall(r'\bwww\.[^\s]+', myString)
    domain_matches = re.findall(r'(?<!@)\b(?:[a-zA-Z0-9-]+\.)+[a-zA-Z]{2,}\b', myString)
    domains = set()
    for u in url_matches + www_matches + domain_matches:
        u = u.rstrip(trailing)
        if not re.match(r'https?://', u):
            u = 'http://' + u
        parsed = urllib.parse.urlparse(u)
        host = parsed.hostname or (parsed.netloc.split(':')[0] if parsed.netloc else None)
        if host:
            domains.add(host.lower())
    results = {}
    for domain in domains:
        api_url = f'http://ip-api.com/json/{domain}'
        if API_KEY:
            api_url += f'?key={urllib.parse.quote(API_KEY)}'
        try:
            resp = requests.get(api_url, timeout=10)
            if resp.status_code == 200:
                data = json.loads(resp.text)
                results[domain] = data
            else:
                results[domain] = None
        except Exception:
            results[domain] = None
    return results

