import smtplib
from email.mime.text import MIMEText
import json
def task_func(smtp_server, smtp_port, smtp_username, smtp_password):
    class EmailRequestHandler(http.server.BaseHTTPRequestHandler):
        def _send_json(self, status, payload, reason=None):
            body = json.dumps(payload).encode('utf-8')
            if reason is None:
                self.send_response(status)
            else:
                self.send_response(status, reason)
            self.send_header('Content-Type', 'application/json')
            self.send_header('Content-Length', str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def do_POST(self):
            try:
                length = int(self.headers.get('Content-Length', '0'))
                raw = self.rfile.read(length) if length > 0 else b''
                data = json.loads(raw.decode('utf-8'))
                if not isinstance(data, dict):
                    raise ValueError('Invalid email data format')
                required = ['subject', 'message', 'to']
                if any(k not in data for k in required):
                    raise ValueError('Missing required fields: subject, message, and to')
                msg = MIMEText(data['message'])
                msg['Subject'] = data['subject']
                msg['From'] = self.smtp_username
                msg['To'] = data['to']
                try:
                    with smtplib.SMTP(self.smtp_server, self.smtp_port) as server:
                        try:
                            server.starttls()
                        except smtplib.SMTPException:
                            pass
                        server.login(self.smtp_username, self.smtp_password)
                        server.sendmail(self.smtp_username, [data['to']], msg.as_string())
                except smtplib.SMTPAuthenticationError:
                    raise
                self._send_json(200, {'status': 'sent'})
            except json.JSONDecodeError:
                self._send_json(400, {'error': 'Invalid JSON'}, reason='Bad Request')
            except ValueError as e:
                self._send_json(400, {'error': str(e)}, reason='Bad Request')
            except smtplib.SMTPAuthenticationError:
                self._send_json(535, {'error': 'Authentication Failed'}, reason='Authentication Failed')
            except Exception:
                self._send_json(500, {'error': 'Internal Server Error'})
    EmailRequestHandler.smtp_server = smtp_server
    EmailRequestHandler.smtp_port = smtp_port
    EmailRequestHandler.smtp_username = smtp_username
    EmailRequestHandler.smtp_password = smtp_password
    return EmailRequestHandler

