def task_func(smtp_server, smtp_port, smtp_username, smtp_password):
    class EmailRequestHandler(http.server.BaseHTTPRequestHandler):
        def _send_json(self, status_code, payload, reason=None):
            body = json.dumps(payload).encode('utf-8')
            if reason is not None:
                self.send_response(status_code, reason)
            else:
                self.send_response(status_code)
            self.send_header('Content-Type', 'application/json')
            self.send_header('Content-Length', str(len(body)))
            self.end_headers()
            self.wfile.write(body)
        def do_POST(self):
            try:
                length_header = self.headers.get('Content-Length')
                length = int(length_header) if length_header is not None else 0
                raw = self.rfile.read(length)
                try:
                    data = json.loads(raw.decode('utf-8'))
                except json.JSONDecodeError:
                    self._send_json(400, {'error': 'Invalid JSON'}, 'Bad Request')
                    return
                if not isinstance(data, dict):
                    raise ValueError('Email data must be a JSON object')
                required = ['subject', 'message', 'to']
                missing = [k for k in required if k not in data]
                if missing:
                    raise ValueError('Missing required fields: ' + ', '.join(missing))
                subject = data['subject']
                message = data['message']
                to_value = data['to']
                if isinstance(to_value, str):
                    recipients = [r.strip() for r in to_value.split(',') if r.strip()]
                elif isinstance(to_value, list):
                    recipients = [str(r).strip() for r in to_value if str(r).strip()]
                else:
                    raise ValueError('Field "to" must be a string or list')
                if not recipients:
                    raise ValueError('No valid recipients provided')
                msg = MIMEText(message)
                msg['Subject'] = str(subject)
                msg['From'] = smtp_username
                msg['To'] = ', '.join(recipients)
                try:
                    with smtplib.SMTP(smtp_server, smtp_port) as server:
                        server.starttls()
                        server.login(smtp_username, smtp_password)
                        server.sendmail(smtp_username, recipients, msg.as_string())
                except smtplib.SMTPAuthenticationError:
                    self._send_json(535, {'error': 'Authentication Failed'}, 'Authentication Failed')
                    return
                self._send_json(200, {'status': 'sent', 'to': recipients})
            except ValueError as e:
                self._send_json(400, {'error': str(e)}, 'Bad Request')
            except smtplib.SMTPException as e:
                self._send_json(500, {'error': 'SMTP Error: ' + str(e)}, 'Internal Server Error')
            except Exception as e:
                self._send_json(500, {'error': 'Server Error: ' + str(e)}, 'Internal Server Error')
    return EmailRequestHandler

