def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    def parse_input(jd):
        if isinstance(jd, (bytes, bytearray)):
            try:
                return json.loads(jd.decode("utf-8"))
            except Exception:
                raise ValueError("Malformed JSON data")
        if isinstance(jd, str):
            try:
                return json.loads(jd)
            except Exception:
                raise ValueError("Malformed JSON data")
        if isinstance(jd, (dict, list)):
            return jd
        raise ValueError("Malformed JSON data")
    def normalize_population(v):
        if isinstance(v, bool):
            raise ValueError("Non-numeric population")
        if isinstance(v, int):
            if v < 0:
                raise ValueError("Negative population")
            return int(v)
        if isinstance(v, float):
            if math.isnan(v) or math.isinf(v) or v < 0:
                raise ValueError("Invalid float population")
            return int(math.floor(v))
        raise ValueError("Non-numeric population")
    data = parse_input(json_data)
    if (isinstance(data, dict) and not data) or (isinstance(data, list) and len(data) == 0):
        raise ValueError("Empty JSON data")
    rows = []
    if isinstance(data, dict):
        for country, pop in data.items():
            if not isinstance(country, str):
                raise ValueError("Non-string country name")
            pop_int = normalize_population(pop)
            rows.append({"Country": country, "Population": pop_int})
    elif isinstance(data, list):
        for item in data:
            if not isinstance(item, dict):
                raise ValueError("Malformed JSON data")
            if "Country" not in item or "Population" not in item:
                raise ValueError("Malformed JSON data")
            country = item["Country"]
