import pandas as pd
import json
import os
import math
def task_func(json_data, output_dir=".", file_name="country_population_report.csv"):
    if json_data is None:
        raise ValueError("Invalid JSON data")
    try:
        if isinstance(json_data, str):
            data = json.loads(json_data)
        else:
            data = json_data
    except Exception:
        raise ValueError("Malformed JSON data")
    if data is None:
        raise ValueError("Empty JSON data")
    records = []
    def add_record(country, population):
        if not isinstance(country, str):
            raise ValueError("Country name must be a string")
        if isinstance(population, bool) or not isinstance(population, (int, float)):
            raise ValueError("Population must be numeric")
        if isinstance(population, float):
            if not math.isfinite(population):
                raise ValueError("Population must be finite")
        if population < 0:
            raise ValueError("Population must be non-negative")
        pop_int = int(math.floor(population)) if isinstance(population, float) else int(population)
        records.append({"Country": country, "Population": pop_int})
    if isinstance(data, dict):
        if not data:
            raise ValueError("Empty JSON data")
        lower_keys = {k.lower() for k in data.keys()}
        if "country" in lower_keys and "population" in lower_keys:
            country_val = None
            population_val = None
            for k, v in data.items():
                lk = k.lower()
                if lk == "country":
                    country_val = v
                elif lk == "population":
                    population_val = v
            if country_val is None or population_val is None:
                raise ValueError("Missing required fields")
            add_record(country_val, population_val)
        else:
            for k, v in data.items():
                add_record(k, v)
    elif isinstance(data, list):
        if len(data) == 0:
            raise ValueError("Empty JSON data")
        for item in data:
            if not isinstance(item, dict):
                raise ValueError("Each item must be an object")
            lm = {str(k).lower(): v for k, v in item.items()}
            if "country" not in lm or "population" not in lm:
                raise ValueError("Missing required fields in an item")
            add_record(lm["country"], lm["population"])
    else:
        raise ValueError("Unsupported JSON structure")
    df = pd.DataFrame(records, columns=["Country", "Population"])
    if df.empty:
        raise ValueError("No valid data to report")
    try:
        if not os.path.exists(output_dir):
            os.makedirs(output_dir, exist_ok=True)
        output_path = os.path.join(output_dir, file_name)
        df.to_csv(output_path, index=False)
    except Exception as e:
        raise IOError(str(e))
    return os.path.abspath(output_path), df

