import json
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import pandas as pd
def task_func(json_data: str, key_path: list):
    try:
        obj = json.loads(json_data)
    except Exception:
        raise ValueError("Data string is empty or corrupted")
    current = obj
    for key in key_path:
        if isinstance(current, dict) and key in current:
            current = current[key]
        else:
            raise KeyError(f"Key not found: {key}")
    def extract_numbers(value, is_root):
        out = []
        if is_root and isinstance(value, str) and not value.strip():
            raise ValueError("Data string is empty or corrupted")
        if isinstance(value, (list, tuple, np.ndarray, pd.Series)):
            for v in list(value):
                out.extend(extract_numbers(v, False))
        elif isinstance(value, (int, float, np.integer, np.floating)):
            out.append(float(value))
        elif isinstance(value, str):
            tmp = value.strip()
            for sep in [',', ';', '|', '\n', '\t']:
                tmp = tmp.replace(sep, ' ')
            for token in tmp.split():
                try:
                    out.append(float(token))
                except:
                    pass
        elif isinstance(value, dict):
            for v in value.values():
                out.extend(extract_numbers(v, False))
        return out
    values = extract_numbers(current, True)
    if not values:
        raise ValueError("No numeric data found")
    df = pd.DataFrame({"value": np.array(values, dtype=float)})
