        if isinstance(cur, dict):
            if p in cur:
                cur = cur[p]
            else:
                raise KeyError
        elif isinstance(cur, list):
            try:
                idx = int(p)
            except:
                raise KeyError
            if idx < 0 or idx >= len(cur):
                raise KeyError
            cur = cur[idx]
        else:
