import json
import pandas as pd
from sklearn.preprocessing import MinMaxScaler
import matplotlib.pyplot as plt
def task_func(json_data: str, data_key: str):
    data = json.loads(json_data)
    current = data
    if data_key:
        parts = data_key.split('.')
        for part in parts:
            if isinstance(current, dict) and part in current:
                current = current[part]
            elif isinstance(current, list) and part.isdigit():
                idx = int(part)
                if idx < 0 or idx >= len(current):
                    raise KeyError(data_key)
                current = current[idx]
            else:
                raise KeyError(data_key)
    def iter_numbers(x):
        if isinstance(x, bool):
            return
        if isinstance(x, (int, float)):
            yield float(x)
        elif isinstance(x, (list, tuple, set)):
            for item in x:
                for y in iter_numbers(item):
                    yield y
        elif isinstance(x, dict):
            for item in x.values():
                for y in iter_numbers(item):
                    yield y
        elif isinstance(x, str):
            try:
                yield float(x.strip())
            except:
                return
    values = list(iter_numbers(current))
    original = pd.Series(values, dtype='float64')
    if original.empty:
        return original, None, None
    scaler = MinMaxScaler()
    normalized_values = scaler.fit_transform(original.values.reshape(-1, 1)).ravel()
    normalized = pd.Series(normalized_values, index=original.index, dtype='float64')
    fig, ax = plt.subplots()
    ax.plot(original.index, original.values, label='Original Data')
    ax.plot(normalized.index, normalized.values, label='Normalized Data')
    ax.set_title('Comparison of Original and Normalized Data')
    ax.set_xlabel('Index')
    ax.set_ylabel('Value')
    ax.legend()
    return original, normalized, ax

